<template><view class="ai-form"><view class="card"><view class="title">AI 尺码助手</view><input v-model="height" type="digit" placeholder="身高 cm"/><input v-model="weight" type="digit" placeholder="体重 kg"/><input v-model="bust" type="digit" placeholder="胸围 cm（选填）"/><input v-model="waist" type="digit" placeholder="腰围 cm（选填）"/><input v-model="hip" type="digit" placeholder="臀围 cm（选填）"/><button @click="advise">获取建议</button><view v-if="result" class="result">{{result}}</view><view class="note">只有商品提供真实尺码表时才会推荐，不会凭空猜尺码。</view></view></view></template>
<script>import {sudiAiSizeAdvice} from "@/api/sudi_ai.js";export default{data(){return{productId:0,sizeChart:[],height:"",weight:"",bust:"",waist:"",hip:"",result:""}},onLoad(o){this.productId=o.product_id||0;try{const parsed=JSON.parse(decodeURIComponent(o.chart||"[]"));this.sizeChart=Array.isArray(parsed)?parsed:[]}catch(e){this.sizeChart=[]}},methods:{async advise(){if(!this.height||!this.weight){return uni.showToast({title:"请填写身高和体重",icon:"none"})}this.result=this.sizeChart.length?"正在根据商品尺码选项分析…":"该商品暂未提供可计算的详细尺码数据";try{const r=await sudiAiSizeAdvice({profile:{height_cm:Number(this.height),weight_kg:Number(this.weight),bust_cm:Number(this.bust||0),waist_cm:Number(this.waist||0),hip_cm:Number(this.hip||0)},size_chart:this.sizeChart});if(r&&r.data&&r.data.reason)this.result=r.data.reason}catch(e){this.result="尺码助手暂时不可用"}}}}</script>
<style scoped>.ai-form{padding:28rpx;background:#f7f7f7;min-height:100vh}.card{background:#fff;padding:28rpx;border-radius:20rpx}.title{font-size:36rpx;font-weight:700;margin-bottom:24rpx}input{height:88rpx;background:#f7f7f7;border-radius:12rpx;padding:0 20rpx;margin-bottom:16rpx}button{background:#ff3366;color:#fff;border-radius:999rpx}.result,.note{margin-top:22rpx;font-size:26rpx;line-height:1.6}.note{color:#999}</style>